<h2 class="mb-3"><?=$title?></h2><div class="card"><div class="card-body"><?=form_open()?><div class="row"><?php foreach($cfg['fields'] as $field=>$label):$v=$row->$field??'';?><div class="col-md-6 mb-3"><label class="form-label"><?=$label?></label><?php if(isset($options[$field])):?><select required class="form-select" name="<?=$field?>"><option value="">Pilih <?=$label?></option><?php foreach($options[$field] as $o):$id=$field==='role_id'?'role_id':($field==='agreement_id'?'agreement_id':'master_item_id');$display=$field==='role_id'?'role_name':($field==='agreement_id'?'agreement_number':'part_number');?><option value="<?=$o->$id?>" <?=$v==$o->$id?'selected':''?>><?=html_escape($o->$display)?></option><?php endforeach;?></select><?php elseif($field==='status'):?><select name="status" class="form-select"><option <?=$v==='Active'?'selected':''?>>Active</option><option <?=$v==='Inactive'?'selected':''?>>Inactive</option></select><?php elseif($field==='description'):?><textarea required name="<?=$field?>" class="form-control"><?=html_escape($v)?></textarea><?php else:$type=in_array($field,array('unit_price'))?'number':(strpos($field,'date')!==false?'date':($field==='password'?'password':'text'));?><input <?=$field==='password'&&$row?'':'required'?> step="0.01" type="<?=$type?>" name="<?=$field?>" value="<?=html_escape($v)?>" class="form-control"><?php endif;?></div><?php endforeach;?></div><button class="btn btn-primary">Simpan</button><a class="btn btn-light" href="<?=site_url('masters/'.$key)?>">Batal</a><?=form_close()?></div></div>
